import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  drawStepBox,
  drawTensor,
  fmtNum,
  Sel
} from '../primitives';

export function renderMlpDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: import('../../components/types').ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number } {
  const dModel = (params.d_model as number) || 512;
  const dFf = (params.d_ff as number) || 2048;
  const activation = String(params.activation || 'gelu');
  const seqLen = 128;
  const totalW = 800;
  const cx = totalW / 2;
  let y = 30;

  // Header
  drawLabel(g, cx, y, 'Feed-Forward Network (MLP)', { size: 16, weight: '700' });
  y += 22;
  drawLabel(g, cx, y, `d_model=${dModel}  d_ff=${dFf}  activation=${activation.toUpperCase()}`, {
    size: 10,
    color: '#888'
  });
  y += 40;

  // Input tensor
  drawTensor(g, cx - 110, y, 220, 30, `x: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  // Step 1: Up-project
  drawStepBox(g, cx - 120, y, 240, 46, 'Up-project to d_ff', {
    step: 1,
    fill: '#e3f2fd',
    stroke: '#1976d2',
    formula: 'h = x · W1 + b1'
  });
  y += 60;

  drawMatrixBlock(g, cx - 60, y, {
    width: 120,
    height: 50,
    label: 'W1',
    sublabel: `[${dModel}, ${dFf}]`,
    fill: '#e3f2fd',
    stroke: '#1976d2'
  });
  y += 70;

  drawArrow(g, cx, y - 20, cx, y - 6, { color: '#78909c' });

  // Step 2: Activation
  drawStepBox(g, cx - 120, y, 240, 46, `${activation.toUpperCase()} Activation`, {
    step: 2,
    fill: '#fce4ec',
    stroke: '#d81b60',
    formula: 'a = activation(h)'
  });
  y += 60;

  // Activation curve
  const plotW = 200;
  const plotH = 80;
  const plotX = cx - plotW / 2;
  const plotY = y;
  g.append('rect')
    .attr('x', plotX)
    .attr('y', plotY)
    .attr('width', plotW)
    .attr('height', plotH)
    .attr('rx', 4)
    .attr('fill', '#fafafa')
    .attr('stroke', '#e0e0e0');

  const fn =
    activation === 'relu'
      ? (x: number) => Math.max(0, x)
      : activation === 'silu'
        ? (x: number) => x / (1 + Math.exp(-x))
        : (x: number) => x * (1 + Math.tanh(Math.sqrt(2 / Math.PI) * (x + 0.044715 * x ** 3))) / 2;

  const points: [number, number][] = [];
  for (let i = 0; i <= 40; i++) {
    const xv = (i / 40) * 6 - 3;
    const yv = fn(xv);
    const px = plotX + 10 + (i / 40) * (plotW - 20);
    const py = plotY + plotH - 10 - ((yv + 1) / 4) * (plotH - 20);
    points.push([px, py]);
  }

  const line = d3.line<[number, number]>().x((d) => d[0]).y((d) => d[1]);
  g.append('path')
    .datum(points)
    .attr('d', line)
    .attr('fill', 'none')
    .attr('stroke', '#d81b60')
    .attr('stroke-width', 2);

  drawLabel(g, cx, plotY + plotH + 14, `${activation.toUpperCase()} curve`, {
    size: 10,
    color: '#666'
  });
  y += plotH + 36;

  // Step 3: Down-project
  drawStepBox(g, cx - 120, y, 240, 46, 'Down-project to d_model', {
    step: 3,
    fill: '#fff3e0',
    stroke: '#f57c00',
    formula: 'out = a · W2 + b2'
  });
  y += 60;

  drawMatrixBlock(g, cx - 60, y, {
    width: 120,
    height: 50,
    label: 'W2',
    sublabel: `[${dFf}, ${dModel}]`,
    fill: '#fff3e0',
    stroke: '#f57c00'
  });
  y += 70;

  // Output tensor
  drawTensor(g, cx - 110, y, 220, 30, `out: [b, ${seqLen}, ${dModel}]`, '#e8f5e9', '#4caf50');
  y += 50;

  // Parameter count
  const totalParams = dModel * dFf * 2;
  drawLabel(g, cx, y, `Total params: ${fmtNum(totalParams)}  (${fmtNum(dModel * dFf)} W1 + ${fmtNum(dFf * dModel)} W2)`, {
    size: 11,
    color: '#1976d2',
    weight: '600'
  });
  y += 28;

  // Explanations
  y = drawExplanation(g, 80, y, totalW - 160,
    'The MLP expands the hidden dimension to create capacity for non-linear transformations. '
    + 'The 4× expansion (d_ff = 4 · d_model) is the default in most Transformer variants because it balances expressiveness and cost.',
    'insight'
  );
  y += 6;

  y = drawExplanation(g, 80, y, totalW - 160,
    `FLOPs per token: 2 · d_model · d_ff · 2 = ${fmtNum(4 * dModel * dFf)}. `
    + 'SwiGLU-style variants use three matrices but only two active matmuls per forward pass, often improving quality.',
    'perf'
  );
  y += 6;

  // Cross-link
  drawComponentLink(g, cx - 70, y, 140, 24, 'transformer-block', 'View Transformer Block ↗', {
    fill: '#e3f2fd',
    stroke: '#1976d2'
  });
  y += 40;

  // Code annotation
  y = drawCodeAnnotation(g, 80, y, totalW - 160,
    'Feed-Forward Network — Transformer (Vaswani et al. 2017)',
    [
      'Two linear projections with a non-linearity in between.',
      `Common modern variants: SwiGLU (Llama, PaLM) and GeGLU (PaLM, GPT-NeoX).`,
      `Params: ${fmtNum(totalParams)}. FLOPs per token: ${fmtNum(4 * dModel * dFf)}.`
    ],
    [
      `self.W1 = nn.Linear(${dModel}, ${dFf})`,
      `self.W2 = nn.Linear(${dFf}, ${dModel})`,
      '',
      `def forward(self, x):  # x: [batch, seq, ${dModel}]`,
      `    h = self.W1(x)             # [batch, seq, ${dFf}]`,
      `    a = F.${activation}(h)`,
      `    return self.W2(a)          # [batch, seq, ${dModel}]`
    ]
  );

  return { width: totalW, height: y + 20 };
}
